window.MPPREP = {"title": "Block 1 · Math & Physics Exam Prep", "passMark": 0.7, "mockSize": 50, "storeKey": "blk1-mp-exam-v1", "figs": {"65": "data:image/png;base64,", "70": "data:image/png;base64,", "68": "data:image/png;base64,", "52": "data:image/png;base64,", "69": "data:image/png;base64,", "53": "data:image/png;base64,", "67": "data:image/png;base64,", "58": "data:image/png;base64,", "59": "data:image/png;base64,", "60": "data:image/png;base64,", "66": "data:image/png;base64,", "54": "data:image/png;base64,", "71": "data:image/png;base64,", "55": "data:image/png;base64,", "56": "data:image/png;base64,", "57": "data:image/png;base64,", "61": "data:image/png;base64,"}, "topics": [{"code": "NUMBERS", "title": "Fractions, Decimals, Binary & Conversions", "ref": "FAA-H-8083-30B Ch.3 & Ch.5", "qs": [{"id": "8379-1", "q": "What is defined as a group of bits representing a complete piece of information?", "options": ["Byte.", "Bit.", "Word."], "correct": 0, "short": "Byte.", "expl": "In a binary system a single 1-or-0 is a BIT; a group of 8 bits handled together as one complete piece of information is a BYTE. A 'word' is a larger, machine-defined group, so the term that names one complete grouped piece of information here is the byte.", "cite": "FAA-H-8083-30B, p. 3-27", "topicName": "Fractions, Decimals, Binary & Conversions", "fig": null}, {"id": "8379-2", "q": "Convert the binary number 00001111 to a whole number.", "options": ["31", "15", "8"], "correct": 1, "short": "15", "expl": "Read a binary number by place value, right to left: 1-2-4-8-16-... For 00001111 the four right-hand 1s are the 8, 4, 2 and 1 places: 8 + 4 + 2 + 1 = 15. Sanity check: 00001111 is the largest 4-bit value, which is always 15.", "cite": "FAA-H-8083-30B, p. 3-27", "topicName": "Fractions, Decimals, Binary & Conversions", "fig": null}, {"id": "8379-3", "q": "Convert 7 to binary form.", "options": ["0011", "1110", "0111"], "correct": 2, "short": "0111", "expl": "Build 7 from binary place values 8-4-2-1: you need 4 + 2 + 1, which turns on the last three bits and leaves the 8s place off -> 0111. Sanity check: 0+4+2+1 = 7.", "cite": "FAA-H-8083-30B, p. 3-27", "topicName": "Fractions, Decimals, Binary & Conversions", "fig": null}, {"id": "8409", "q": "Select the fraction which is equal to 0.0250.", "options": ["1/40", "1/4", "1/400"], "correct": 0, "short": "1/40", "expl": "Turn the decimal into a fraction: 0.0250 = 25/1000. Reduce by dividing top and bottom by 25 -> 1/40. Sanity check: 1 ÷ 40 = 0.025.", "cite": "FAA-H-8083-30B, p. 3-6", "topicName": "Fractions, Decimals, Binary & Conversions", "fig": null}, {"id": "8410", "q": "1.21875 is equal to", "options": ["83/64", "39/32", "19/16"], "correct": 1, "short": "39/32", "expl": "The whole part is 1; the decimal .21875 = 21875/100000, which reduces to 7/32. So 1.21875 = 1 + 7/32 = 39/32 as an improper fraction. Sanity check: 39 ÷ 32 = 1.21875.", "cite": "FAA-H-8083-30B, p. 3-6", "topicName": "Fractions, Decimals, Binary & Conversions", "fig": null}, {"id": "8416", "q": "Select the fractional equivalent for a 0.0625 inch thick sheet of aluminum.", "options": ["3/64", "1/32", "1/16"], "correct": 2, "short": "1/16", "expl": "0.0625 is one of the common sheet-metal gauge decimals on the decimal-equivalent chart: 0.0625 = 1/16 inch. Sanity check: 1 ÷ 16 = 0.0625.", "cite": "FAA-H-8083-30B, p. 3-7", "topicName": "Fractions, Decimals, Binary & Conversions", "fig": null}, {"id": "8416-1", "q": "Examples of units used in the conventional (U.S. or English) measurement include", "options": ["inch, ounce, and pound.", "inch, meter, and gram.", "inch, kilo, and liter."], "correct": 0, "short": "inch, ounce, and pound.", "expl": "The conventional (U.S./English) system uses inch, ounce, and pound. Meter, gram, kilo, and liter belong to the metric system, so the all-English set is inch-ounce-pound.", "cite": "FAA-H-8083-30B, p. 3-26", "topicName": "Fractions, Decimals, Binary & Conversions", "fig": null}, {"id": "8418", "q": "Select the decimal which is most nearly equal to 77/64.", "options": ["0.08311", "1.2031", "0.8311"], "correct": 1, "short": "1.2031", "expl": "Divide the fraction out: 77 ÷ 64 = 1.203125, which rounds to 1.2031. Sanity check: 77/64 is a little more than 1 (64/64), so a value just over 1.2 is right.", "cite": "FAA-H-8083-30B, p. 3-7", "topicName": "Fractions, Decimals, Binary & Conversions", "fig": null}, {"id": "8425", "q": "A blueprint shows a hole of 0.17187 to be drilled. Which fraction size drill bit is most nearly equal?", "options": ["9/32", "11/32", "11/64"], "correct": 2, "short": "11/64", "expl": "Convert the fraction candidates to decimals and match 0.17187: 11/64 = 0.171875, the closest fit. (9/32 = 0.281, 11/32 = 0.344 are far off.) So the 11/64 drill is the nearest size.", "cite": "FAA-H-8083-30B, p. 3-7", "topicName": "Fractions, Decimals, Binary & Conversions", "fig": null}, {"id": "8426", "q": "Which decimal is most nearly equal to a bend radius of 31/64?", "options": ["0.4844", "0.2065", "0.3164"], "correct": 0, "short": "0.4844", "expl": "Divide the bend-radius fraction: 31 ÷ 64 = 0.484375, which is most nearly 0.4844. Sanity check: 31/64 is just under 1/2 (32/64 = 0.5), so about 0.48 is right.", "cite": "FAA-H-8083-30B, p. 3-7", "topicName": "Fractions, Decimals, Binary & Conversions", "fig": null}, {"id": "8428", "q": "The radius of a piece of round stock is 7/32. Select the decimal which is most nearly equal to the diameter.", "options": ["0.2187", "0.4375", "0.3531"], "correct": 1, "short": "0.4375", "expl": "Radius is half the diameter, so the diameter is 2 × 7/32 = 14/32 = 7/16. As a decimal, 7 ÷ 16 = 0.4375. Sanity check: double the 0.21875 radius = 0.4375.", "cite": "FAA-H-8083-30B, p. 3-7", "topicName": "Fractions, Decimals, Binary & Conversions", "fig": null}]}, {"code": "RATIO", "title": "Ratio & Proportion", "ref": "FAA-H-8083-30B Ch.3 & Ch.5", "qs": [{"id": "8413", "q": "What is the speed of a spur gear with 42 teeth driven by a pinion gear with 14 teeth turning 420 RPM?", "options": ["140 RPM.", "588 RPM.", "160 RPM."], "correct": 0, "short": "140 RPM.", "expl": "Gear speeds are inversely proportional to tooth count: (driver teeth × driver rpm) = (driven teeth × driven rpm). So 14 × 420 = 42 × N, N = 5880 ÷ 42 = 140 rpm. The big 42-tooth gear turns slower than its 14-tooth driver — 140 rpm is correct.", "cite": "FAA-H-8083-30B, p. 3-8", "topicName": "Ratio & Proportion", "fig": null}, {"id": "8419", "q": "An airplane flying a distance of 750 miles used 60 gallons of gasoline. How many gallons will it need to travel 2,500 miles?", "options": ["31,250", "200", "9,375"], "correct": 1, "short": "200", "expl": "Set up a proportion, gallons to miles: 60/750 = x/2500. Cross-multiply: x = 60 × 2500 ÷ 750 = 200 gallons. Sanity check: 2500 miles is about 3.3× as far as 750, and 3.3 × 60 ≈ 200.", "cite": "FAA-H-8083-30B, p. 3-8", "topicName": "Ratio & Proportion", "fig": null}, {"id": "8420", "q": "What is the speed ratio of an input gear with 36 teeth meshed to a gear with 20 teeth?", "options": ["9:5", "1:0.56", "1:1.8"], "correct": 2, "short": "1:1.8", "expl": "Speed ratio is input teeth to output teeth reduced: 36:20 divides by 4 to 9:5, and 9:5 = 1:0.56 when written as 1-to-something (5 ÷ 9 = 0.56). So the ratio is 1:0.56.", "cite": "FAA-H-8083-30B, p. 3-7", "topicName": "Ratio & Proportion", "fig": null}, {"id": "8421", "q": "A pinion gear with 14 teeth is driving a spur gear with 42 teeth at 140 RPM. Determine the speed of the pinion gear.", "options": ["420 RPM.", "588 RPM.", "126 RPM."], "correct": 0, "short": "420 RPM.", "expl": "Tooth count and speed are inversely proportional: 14 × N = 42 × 140. N = 5880 ÷ 14 = 420 rpm. The small pinion always spins faster than the big gear it drives, so 420 rpm is right.", "cite": "FAA-H-8083-30B, p. 3-8", "topicName": "Ratio & Proportion", "fig": null}, {"id": "8430", "q": "What is the ratio of 10 feet to 30 inches?", "options": ["1:3", "4:1", "3:1"], "correct": 1, "short": "4:1", "expl": "Put both in the same unit: 10 feet = 120 inches. The ratio 120:30 reduces (divide by 30) to 4:1. Sanity check: 120 is four times 30.", "cite": "FAA-H-8083-30B, p. 3-7", "topicName": "Ratio & Proportion", "fig": null}, {"id": "8435", "q": "What is the ratio of a gasoline fuel load of 200 gallons to one of 1,680 pounds?", "options": ["2:3", "5:42", "5:7"], "correct": 2, "short": "5:7", "expl": "Convert gallons of gasoline to pounds (avgas ≈ 6 lb/gal): 200 gal × 6 = 1,200 lb. The ratio 1,200:1,680 reduces (divide by 240) to 5:7. Sanity check: 5 × 240 = 1,200 and 7 × 240 = 1,680.", "cite": "FAA-H-8083-30B, p. 3-7", "topicName": "Ratio & Proportion", "fig": null}]}, {"code": "PERCENT", "title": "Percentage", "ref": "FAA-H-8083-30B Ch.3 & Ch.5", "qs": [{"id": "8412", "q": "Express 7/8 as a percent.", "options": ["87.5 percent.", "8.75 percent.", ".875 percent."], "correct": 0, "short": "87.5 percent.", "expl": "Change the fraction to a percent by dividing and moving the decimal two places: 7 ÷ 8 = 0.875, then ×100 = 87.5 percent. Sanity check: 7/8 is close to a whole, so a value near 90 percent is right.", "cite": "FAA-H-8083-30B, p. 3-10", "topicName": "Percentage", "fig": null}, {"id": "8414", "q": "An engine develops 108 horsepower at 87 percent power. What horsepower would be developed at 65 percent power?", "options": ["70", "81", "61"], "correct": 1, "short": "81", "expl": "First back out to 100 percent power: 108 hp ÷ 0.87 = 124.14 hp at full power. Then take 65 percent of that: 124.14 × 0.65 = 80.7 ≈ 81 hp.", "cite": "FAA-H-8083-30B, p. 3-11", "topicName": "Percentage", "fig": null}, {"id": "8417", "q": "Express 5/8 as a percent.", "options": [".625 percent.", "6.25 percent.", "62.5 percent."], "correct": 2, "short": "62.5 percent.", "expl": "Divide, then shift two places: 5 ÷ 8 = 0.625, ×100 = 62.5 percent. Sanity check: 5/8 is just over half, so a bit over 60 percent fits.", "cite": "FAA-H-8083-30B, p. 3-10", "topicName": "Percentage", "fig": null}, {"id": "8422", "q": "The parts department’s profit is 12 percent on a new part. How much does the part cost if the selling price is $145.60?", "options": ["$130.00", "$128.13", "$125.60"], "correct": 0, "short": "$130.00", "expl": "The $145.60 selling price is cost plus 12 percent, i.e. 112 percent of cost. Cost = 145.60 ÷ 1.12 = $130.00. Sanity check: 130 × 1.12 = 145.60.", "cite": "FAA-H-8083-30B, p. 3-11", "topicName": "Percentage", "fig": null}, {"id": "8423", "q": "If an engine is turning 1,965 rpm at 65 percent power, what is its maximum rpm?", "options": ["2,653", "3,023", "3,242"], "correct": 1, "short": "3,023", "expl": "1,965 rpm is 65 percent of maximum, so divide to find 100 percent: 1,965 ÷ 0.65 = 3,023 rpm. Sanity check: 3,023 × 0.65 ≈ 1,965.", "cite": "FAA-H-8083-30B, p. 3-11", "topicName": "Percentage", "fig": null}, {"id": "8424", "q": "An engine of 98 horsepower maximum is running at 75 percent power. What is the horsepower being developed?", "options": ["87.00", "33.30", "73.50"], "correct": 2, "short": "73.50", "expl": "Take 75 percent of the maximum: 98 hp × 0.75 = 73.5 hp. Sanity check: three-quarters of 98 is a little under 74.", "cite": "FAA-H-8083-30B, p. 3-10", "topicName": "Percentage", "fig": null}, {"id": "8427", "q": "Sixty-five engines are what percent of 80 engines?", "options": ["81 percent.", "65 percent.", "52 percent."], "correct": 0, "short": "81 percent.", "expl": "To find what percent one number is of another, divide the part by the whole: 65 ÷ 80 = 0.8125, ×100 ≈ 81 percent. Sanity check: 65 is a bit more than three-quarters of 80, and 81 percent fits.", "cite": "FAA-H-8083-30B, p. 3-10", "topicName": "Percentage", "fig": null}, {"id": "8429", "q": "Maximum life for a certain part is 1100 hours. Recently, 15 of these parts were removed from different aircraft with an average life of 835.3 hours. What percent of the maximum part life has been achieved?", "options": ["76.9 percent.", "75.9 percent.", "75.0 percent."], "correct": 1, "short": "75.9 percent.", "expl": "Percent of life used = achieved ÷ maximum: 835.3 ÷ 1,100 = 0.759, ×100 = 75.9 percent. Sanity check: 835 is about three-quarters of 1,100.", "cite": "FAA-H-8083-30B, p. 3-10", "topicName": "Percentage", "fig": null}]}, {"code": "POWERS", "title": "Powers, Roots & Scientific Notation", "ref": "FAA-H-8083-30B Ch.3 & Ch.5", "qs": [{"id": "8379", "q": "What power of 10 is equal to 1,000,000,000?", "options": ["10 to the ninth power.", "10 to the sixth power.", "10 to the tenth power."], "correct": 0, "short": "10 to the ninth power.", "expl": "The power of ten equals the number of zeros: 1,000,000,000 has nine zeros, so it is 10 to the ninth power (10⁹). Sanity check: count the places the decimal moves from 1.0 to the full number — nine.", "cite": "FAA-H-8083-30B, p. 3-12", "topicName": "Powers, Roots & Scientific Notation", "fig": null}, {"id": "8380", "q": "Find the square root of 1,746.", "options": ["41.7752", "41.7852", "40.7742"], "correct": 1, "short": "41.7852", "expl": "A square root is the number that times itself gives the original. √1,746 ≈ 41.7852 (41.7852 × 41.7852 ≈ 1,746). Of the choices, 41.7852 is the accurate one.", "cite": "FAA-H-8083-30B, p. 3-12", "topicName": "Powers, Roots & Scientific Notation", "fig": null}, {"id": "8382", "q": "Find the square root of 3722.1835.", "options": ["61.00971", "61.00", "61.0097"], "correct": 2, "short": "61.0097", "expl": "√3,722.1835 ≈ 61.0097 (61.0097 × 61.0097 ≈ 3,722). Carry enough decimal places to separate it from the near-miss distractors — 61.0097 is correct.", "cite": "FAA-H-8083-30B, p. 3-12", "topicName": "Powers, Roots & Scientific Notation", "fig": null}, {"id": "8383", "q": "Which of the following is equal to the square root of (-1776) ÷ (-2) – 632?", "options": ["16", "128", "256"], "correct": 0, "short": "16", "expl": "Work inside first: (-1776) ÷ (-2) = 888 (negative ÷ negative = positive), then 888 – 632 = 256. Finally √256 = 16. Sanity check: 16 × 16 = 256.", "cite": "FAA-H-8083-30B, p. 3-12", "topicName": "Powers, Roots & Scientific Notation", "fig": null}, {"id": "8384", "q": "64 cubed equals", "options": ["4", "262,144", "192"], "correct": 1, "short": "262,144", "expl": "'Cubed' means the number times itself three times: 64 × 64 × 64 = 262,144. Sanity check: 64² = 4,096, and 4,096 × 64 = 262,144.", "cite": "FAA-H-8083-30B, p. 3-12", "topicName": "Powers, Roots & Scientific Notation", "fig": null}, {"id": "8385", "q": "Find the value of 10 raised to the negative sixth power.", "options": ["0.000010", "0.0001", "0.000001"], "correct": 2, "short": "0.000001", "expl": "A negative power of ten is a decimal: 10⁻⁶ = 1 ÷ 1,000,000 = 0.000001 (six places after the point). Sanity check: the exponent 6 equals the number of decimal places.", "cite": "FAA-H-8083-30B, p. 3-12", "topicName": "Powers, Roots & Scientific Notation", "fig": null}, {"id": "8386", "q": "What is the square root of 4 raised to the fifth power?", "options": ["32", "64", "20"], "correct": 0, "short": "32", "expl": "Take the root first: √4 = 2. Then raise to the fifth power: 2⁵ = 2×2×2×2×2 = 32. Sanity check: 2⁵ is a familiar value, 32.", "cite": "FAA-H-8083-30B, p. 3-12", "topicName": "Powers, Roots & Scientific Notation", "fig": null}, {"id": "8387", "q": "The number 3.47 × 10 to the negative fourth power is equal to", "options": [".00347", ".000347", "34,700"], "correct": 1, "short": ".000347", "expl": "A negative exponent moves the decimal LEFT: 3.47 × 10⁻⁴ shifts the decimal four places left = 0.000347. Sanity check: negative power = small number, four places over.", "cite": "FAA-H-8083-30B, p. 3-13", "topicName": "Powers, Roots & Scientific Notation", "fig": null}, {"id": "8388", "q": "Which alternative answer is equal to 16,300?", "options": ["1.63 × 10 to the negative third power.", "163 × 10 to the negative second power.", "1.63 × 10 to the fourth power."], "correct": 2, "short": "1.63 × 10 to the fourth power.", "expl": "In scientific notation the coefficient sits between 1 and 10 with a power of ten setting the size: 1.63 × 10⁴ = 16,300 (move the decimal four places right). Sanity check: 10⁴ = 10,000, and 1.63 × 10,000 = 16,300.", "cite": "FAA-H-8083-30B, p. 3-13", "topicName": "Powers, Roots & Scientific Notation", "fig": null}, {"id": "8389", "q": "Find the square root of 124.9924.", "options": ["1,118 × 10 to the negative second power.", "111.8 × 10 to the third power.", ".1118 × 10 to the negative second power."], "correct": 0, "short": "1,118 × 10 to the negative second power.", "expl": "√124.9924 ≈ 11.18. Written in scientific-notation form that matches a choice, 11.18 = 1,118 × 10⁻² (1,118 with the decimal moved two places left). Sanity check: 1,118 × 0.01 = 11.18, and 11.18² ≈ 125.", "cite": "FAA-H-8083-30B, p. 3-13", "topicName": "Powers, Roots & Scientific Notation", "fig": null}, {"id": "8390", "q": "What is the square root of 16 raised to the fourth power?", "options": ["1,024", "256", "4,096"], "correct": 1, "short": "256", "expl": "Take the square root first: √16 = 4. Then raise to the fourth power: 4⁴ = 4×4×4×4 = 256. Sanity check: 4² = 16, 16² = 256.", "cite": "FAA-H-8083-30B, p. 3-12", "topicName": "Powers, Roots & Scientific Notation", "fig": null}, {"id": "8392", "q": "The result of 7 raised to the third power plus the square root of 39 is equal to", "options": [".34924", "343.24", "349.24"], "correct": 2, "short": "349.24", "expl": "Do each part: 7³ = 343, and √39 ≈ 6.24. Add them: 343 + 6.24 = 349.24. Sanity check: the cube dominates, so an answer near 349 is right.", "cite": "FAA-H-8083-30B, p. 3-12", "topicName": "Powers, Roots & Scientific Notation", "fig": null}, {"id": "8393", "q": "Find the square root of 1,824.", "options": [".42708 × 10 to the second power.", "42.708 × 10 to the negative second power.", ".42708."], "correct": 0, "short": ".42708 × 10 to the second power.", "expl": "√1,824 ≈ 42.708. To match a scientific-notation choice, 42.708 = .42708 × 10² (decimal moved two places, ×100). Sanity check: .42708 × 100 = 42.708, and 42.708² ≈ 1,824.", "cite": "FAA-H-8083-30B, p. 3-13", "topicName": "Powers, Roots & Scientific Notation", "fig": null}, {"id": "8393-1", "q": "(Refer to Figure 65.) Which of the figures is using scientific notation?", "options": ["2.", "1.", "both 1 and 2."], "correct": 1, "short": "1.", "expl": "Scientific notation requires the coefficient to be a single digit from 1 through 9 followed by a power of ten. The figure that follows that rule (one non-zero digit before the decimal, times a power of ten) is illustration 1.", "cite": "FAA-H-8083-30B, p. 3-13", "topicName": "Powers, Roots & Scientific Notation", "fig": "65"}, {"id": "8393-2", "q": "(Refer to Figure 70.) Which alternative answer is equal to 5.59?", "options": ["2.", "3.", "1."], "correct": 2, "short": "1.", "expl": "Evaluate each figure's expression and compare to 5.59; the one that works out to 5.59 is illustration 1. Read the powers of ten carefully — a sign or place error is what the other two illustrations trip on.", "cite": "FAA-H-8083-30B, p. 3-13", "topicName": "Powers, Roots & Scientific Notation", "fig": "70"}, {"id": "8393-4", "q": "(Refer to Figure 68.) Which results in the largest number?", "options": ["2.", "1.", "3."], "correct": 0, "short": "2.", "expl": "Compare the three figure expressions by first putting each in plain (standard) form, then pick the biggest — illustration 2 works out to the highest total. Positive powers of ten make a value big; negative ones make it small.", "cite": "FAA-H-8083-30B, p. 3-13", "topicName": "Powers, Roots & Scientific Notation", "fig": "68"}]}, {"code": "ALGEBRA", "title": "Algebra, Signed Numbers & Order of Operations", "ref": "FAA-H-8083-30B Ch.3 & Ch.5", "qs": [{"id": "8381", "q": "(Refer to Figure 52.) Solve the equation.", "options": ["5", "115", "4.472"], "correct": 0, "short": "5", "expl": "Follow order of operations: clear parentheses/exponents, do the roots and powers, then combine. Working the figure's expression through in that order gives 5. Any number to the zero power is 1, which is the step most people miss.", "cite": "FAA-H-8083-30B, p. 3-17", "topicName": "Algebra, Signed Numbers & Order of Operations", "fig": "52"}, {"id": "8383-1", "q": "(Refer to Figure 69.) Solve the equation.", "options": ["60", "12", "76"], "correct": 1, "short": "12", "expl": "Solve the figured equation left-to-right by the order of operations — parentheses and exponents first, then multiply/divide, then add/subtract. Worked through, the result is 12.", "cite": "FAA-H-8083-30B, p. 3-17", "topicName": "Algebra, Signed Numbers & Order of Operations", "fig": "69"}, {"id": "8391", "q": "(Refer to Figure 53.) Solve the equation.", "options": [".0297", ".1680", ".0419"], "correct": 2, "short": ".0419", "expl": "Evaluate the figure's expression using the correct order of operations; keeping the decimal places straight yields .0419. Small-number problems like this punish rounding too early — carry the digits.", "cite": "FAA-H-8083-30B, p. 3-17", "topicName": "Algebra, Signed Numbers & Order of Operations", "fig": "53"}, {"id": "8393-3", "q": "(Refer to Figure 67.) Solve the equation.", "options": ["0.042.", "5.58.", "12.16."], "correct": 0, "short": "0.042.", "expl": "Apply order of operations to the figured equation; the answer is 0.042. Watch the decimal point — the distractors are off by full powers of ten from doing a step out of order.", "cite": "FAA-H-8083-30B, p. 3-17", "topicName": "Algebra, Signed Numbers & Order of Operations", "fig": "67"}, {"id": "8432", "q": "Solve the equation. [(4 × -3)+(-9 × 2)] ÷ 2 =", "options": ["-30", "-15", "-5"], "correct": 1, "short": "-15", "expl": "Inside the brackets first: (4 × -3) = -12 and (-9 × 2) = -18; add them: -12 + -18 = -30. Then divide: -30 ÷ 2 = -15. Sanity check: two negatives added stay negative.", "cite": "FAA-H-8083-30B, p. 3-17", "topicName": "Algebra, Signed Numbers & Order of Operations", "fig": null}, {"id": "8433", "q": "Solve the equation. (64 × 3/8) ÷ 3/4 =", "options": ["18", "24", "32"], "correct": 2, "short": "32", "expl": "Multiply first: 64 × 3/8 = 24. Then divide by a fraction by inverting and multiplying: 24 ÷ 3/4 = 24 × 4/3 = 32. Sanity check: dividing by 3/4 makes the number bigger.", "cite": "FAA-H-8083-30B, p. 3-17", "topicName": "Algebra, Signed Numbers & Order of Operations", "fig": null}, {"id": "8434", "q": "Solve the equation. (32 × 3/8) ÷ 1/6 =", "options": ["72", "12", "2"], "correct": 0, "short": "72", "expl": "Multiply: 32 × 3/8 = 12. Divide by 1/6 = multiply by 6: 12 × 6 = 72. Sanity check: dividing by a small fraction (1/6) makes it much larger.", "cite": "FAA-H-8083-30B, p. 3-17", "topicName": "Algebra, Signed Numbers & Order of Operations", "fig": null}, {"id": "8436", "q": "Solve the equation. 1/2 (-30 + 34) 5 =", "options": ["95", "10", "160"], "correct": 1, "short": "10", "expl": "Parentheses first: (-30 + 34) = 4. Then apply the ½ and the 5 (multiplication): ½ × 4 × 5 = 2 × 5 = 10. Sanity check: half of 4 is 2, times 5 is 10.", "cite": "FAA-H-8083-30B, p. 3-17", "topicName": "Algebra, Signed Numbers & Order of Operations", "fig": null}, {"id": "8437", "q": "(Refer to Figure 58.) Solve the equation.", "options": ["174.85", "68.037", "14.002"], "correct": 2, "short": "14.002", "expl": "Solve the figured equation in order-of-operations sequence; the result is 14.002. Do the grouped terms and any powers before the final add/subtract to avoid the larger distractor values.", "cite": "FAA-H-8083-30B, p. 3-17", "topicName": "Algebra, Signed Numbers & Order of Operations", "fig": "58"}, {"id": "8438", "q": "(Refer to Figure 59.) Solve the equation.", "options": ["-5.20", "+31.25", "-31.25"], "correct": 0, "short": "-5.20", "expl": "Work the figured expression using the sign rules and order of operations; it comes to -5.20. Track the negative signs through each step — that is where +31.25 and -31.25 come from as traps.", "cite": "FAA-H-8083-30B, p. 3-17", "topicName": "Algebra, Signed Numbers & Order of Operations", "fig": "59"}, {"id": "8439", "q": "Solve the equation. 4 – 3[-6(2 + 3) + 4] =", "options": ["-25", "82", "-71"], "correct": 1, "short": "82", "expl": "Innermost first: (2 + 3) = 5, then -6 × 5 = -30, plus 4 = -26. Multiply by -3: -3 × -26 = 78. Then 4 + 78 = 82. Sanity check: negative times negative gave a positive 78.", "cite": "FAA-H-8083-30B, p. 3-18", "topicName": "Algebra, Signed Numbers & Order of Operations", "fig": null}, {"id": "8440", "q": "Solve the equation. -6[-9(-8 + 4) – 2(7 + 3)] =", "options": ["-332", "216", "-96"], "correct": 2, "short": "-96", "expl": "Work inside out: (-8 + 4) = -4, so -9 × -4 = 36; (7 + 3) = 10, so 2 × 10 = 20; 36 – 20 = 16. Then -6 × 16 = -96. Sanity check: the outside -6 flips the sign negative.", "cite": "FAA-H-8083-30B, p. 3-18", "topicName": "Algebra, Signed Numbers & Order of Operations", "fig": null}, {"id": "8441", "q": "Solve the equation. (-3 + 2)(-12 – 4) + (-4 + 6) × 3", "options": ["22", "20", "28"], "correct": 0, "short": "22", "expl": "Handle each group: (-3 + 2) = -1 and (-12 – 4) = -16, so (-1)(-16) = 16. Then (-4 + 6) = 2, and 2 × 3 = 6. Add: 16 + 6 = 22. Sanity check: negative times negative made 16 positive.", "cite": "FAA-H-8083-30B, p. 3-17", "topicName": "Algebra, Signed Numbers & Order of Operations", "fig": null}, {"id": "8442", "q": "(Refer to Figure 60.) Solve the equation.", "options": ["11.7", "11.9", "11.09"], "correct": 1, "short": "11.9", "expl": "Evaluate the figured equation by the order of operations; carrying the decimals gives 11.9. The near-miss answers come from rounding a middle step, so keep full precision until the end.", "cite": "FAA-H-8083-30B, p. 3-17", "topicName": "Algebra, Signed Numbers & Order of Operations", "fig": "60"}, {"id": "8442-1", "q": "(Refer to the Figure 66.) Solve the equation.", "options": ["35,998", "62,208", "36,002"], "correct": 2, "short": "36,002", "expl": "Work the figured expression in proper order; the result is 36,002. A large-number problem like this hinges on doing the powers/products before the final add — one misplaced step gives 62,208.", "cite": "FAA-H-8083-30B, p. 3-17", "topicName": "Algebra, Signed Numbers & Order of Operations", "fig": "66"}]}, {"code": "GEOMETRY", "title": "Area, Volume & Geometry", "ref": "FAA-H-8083-30B Ch.3 & Ch.5", "qs": [{"id": "8394-1", "q": "What is the surface area of a cube where a side (edge) measures 7.25 inches?", "options": ["315.375 square inches.", "381.078 cubic inches.", "52.5625 square inches."], "correct": 0, "short": "315.375 square inches.", "expl": "A cube has six identical square faces. One face = side² = 7.25² = 52.5625 sq in. Six faces: 52.5625 × 6 = 315.375 square inches. Note the unit is square inches (area), not cubic.", "cite": "FAA-H-8083-30B, p. 3-24", "topicName": "Area, Volume & Geometry", "fig": null}, {"id": "8395", "q": "(Refer to Figure 54.) Compute the area of the trapezoid.", "options": ["60 square feet.", "52.5 square feet.", "76.5 square feet."], "correct": 1, "short": "52.5 square feet.", "expl": "Trapezoid area = altitude × average of the two parallel bases. Here altitude 5 ft, bases 9 ft and 12 ft (average 10.5 ft): 5 × 10.5 = 52.5 square feet.", "cite": "FAA-H-8083-30B, p. 3-18", "topicName": "Area, Volume & Geometry", "fig": "54"}, {"id": "8395-1", "q": "(Refer to Figure 71.) What is the volume of a sphere with a radius of 4.5 inches?", "options": ["47.71 cubic inches.", "381.7 square inches.", "381.7 cubic inches."], "correct": 2, "short": "381.7 cubic inches.", "expl": "Sphere volume = (1/6) × π × D³. With radius 4.5 in the diameter is 9 in: (1/6) × π × 9³ = (1/6) × π × 729 = 381.7 cubic inches. The unit is cubic inches (volume).", "cite": "FAA-H-8083-30B, p. 3-22", "topicName": "Area, Volume & Geometry", "fig": "71"}, {"id": "8396", "q": "What size sheet of metal is required to fabricate a cylinder 20 inches long and 8 inches in diameter? (Note: C = π × D)", "options": ["20 inches × 25-9/64 inches.", "20 inches × 25-5/32 inches.", "20 inches × 24-9/64 inches."], "correct": 0, "short": "20 inches × 25-9/64 inches.", "expl": "A rolled cylinder's width equals its circumference, C = π × D = π × 8 = 25.1327 in ≈ 25-9/64 in; the length equals the cylinder length, 20 in. So the blank is 20 in × 25-9/64 in.", "cite": "FAA-H-8083-30B, p. 3-19", "topicName": "Area, Volume & Geometry", "fig": null}, {"id": "8397", "q": "(Refer to Figure 55.) Find the area of the triangle shown.", "options": ["12 square inches.", "6 square inches.", "15 square inches."], "correct": 1, "short": "6 square inches.", "expl": "Triangle area = ½ × base × altitude = ½ × 4 × 3 = 6 square inches. Sanity check: it is half of the 4×3 = 12 rectangle.", "cite": "FAA-H-8083-30B, p. 3-18", "topicName": "Area, Volume & Geometry", "fig": "55"}, {"id": "8399", "q": "A rectangular-shaped fuel tank measures 60 inches in length, 30 inches in width, and 12 inches in depth. How many cubic feet are within the tank?", "options": ["15.0", "21.0", "12.5"], "correct": 2, "short": "12.5", "expl": "Volume of a rectangular tank = length × width × depth, then convert to cubic feet. 60 × 30 × 12 = 21,600 cubic inches; ÷ 1,728 (cu in per cu ft) = 12.5 cubic feet.", "cite": "FAA-H-8083-30B, p. 3-20", "topicName": "Area, Volume & Geometry", "fig": null}, {"id": "8400", "q": "Select the container size that will be equal in volume to 60 gallons of fuel. (7.5 gal = 1 cu ft)", "options": ["8.0 cubic feet.", "7.5 cubic feet.", "8.5 cubic feet."], "correct": 0, "short": "8.0 cubic feet.", "expl": "At 7.5 gallons per cubic foot, the volume needed = 60 ÷ 7.5 = 8.0 cubic feet. Sanity check: 8 cu ft × 7.5 gal/cu ft = 60 gal.", "cite": "FAA-H-8083-30B, p. 3-23", "topicName": "Area, Volume & Geometry", "fig": null}, {"id": "8401", "q": "(Refer to Figure 56.) Compute the area of the trapezoid.", "options": ["24 square feet.", "10 square feet.", "48 square feet."], "correct": 1, "short": "10 square feet.", "expl": "Trapezoid area = altitude × average of the bases. Altitude 2 ft, bases 4 ft and 6 ft (average 5 ft): 2 × 5 = 10 square feet.", "cite": "FAA-H-8083-30B, p. 3-18", "topicName": "Area, Volume & Geometry", "fig": "56"}, {"id": "8402", "q": "(Refer to Figure 57.) Determine the area of the triangle formed by points A, B, and C. A to B = 7.5 inches A to D = 16.8 inches", "options": ["42 square inches.", "126 square inches.", "63 square inches."], "correct": 2, "short": "63 square inches.", "expl": "Triangle area = ½ × base × altitude. The base (A to D) is 16.8 in and the altitude (A to B) is 7.5 in: (16.8 × 7.5) ÷ 2 = 126 ÷ 2 = 63 square inches.", "cite": "FAA-H-8083-30B, p. 3-18", "topicName": "Area, Volume & Geometry", "fig": "57"}, {"id": "8404", "q": "How many gallons of fuel will be contained in a rectangular-shaped tank which measures 2 feet in width, 3 feet in length, and 1 foot 8 inches in depth? (7.5 gal = 1 cu ft)", "options": ["75", "66.6", "45"], "correct": 0, "short": "75", "expl": "Put every dimension in feet: 1 ft 8 in = 1.667 ft (20 in ÷ 12). Volume = 3 × 2 × 1.667 = 10 cubic feet. At 7.5 gal/cu ft: 10 × 7.5 = 75 gallons.", "cite": "FAA-H-8083-30B, p. 3-20", "topicName": "Area, Volume & Geometry", "fig": null}, {"id": "8405", "q": "A rectangular shaped fuel tank measures 27-1/2 inches in length, 3/4 foot in width, and 8-1/4 inches in depth. How many gallons will the tank contain? (231 cu in = 1 gal)", "options": ["7.366", "8.83", "170.156"], "correct": 1, "short": "8.83", "expl": "Convert to inches: 3/4 ft = 9 in. Volume = 27.5 × 9 × 8.25 = 2,041.875 cubic inches. Divide by 231 (cu in per gallon): 2,041.875 ÷ 231 = 8.83 gallons.", "cite": "FAA-H-8083-30B, p. 3-20", "topicName": "Area, Volume & Geometry", "fig": null}, {"id": "8407", "q": "A rectangular-shaped fuel tank measures 37-1/2 inches in length, 14 inches in width, and 8-1/4 inches in depth. How many cubic inches are within the tank?", "options": ["59.75", "433.125", "4,331.25"], "correct": 2, "short": "4,331.25", "expl": "Volume of a rectangular tank = length × width × depth = 37.5 × 14 × 8.25 = 4,331.25 cubic inches. The answer is asked in cubic inches, so no gallon/foot conversion is needed.", "cite": "FAA-H-8083-30B, p. 3-20", "topicName": "Area, Volume & Geometry", "fig": null}]}, {"code": "APPLIED", "title": "Applied Aircraft Math (Displacement, Ratios, Force)", "ref": "FAA-H-8083-30B Ch.3 & Ch.5", "qs": [{"id": "8394", "q": "The total piston displacement in a reciprocating engine is", "options": ["the volume displaced by all the pistons during one revolution of the crankshaft.", "the volume displaced by only one piston during one-half revolution of the crankshaft.", "the volume displaced by all the pistons during two revolutions of the crankshaft."], "correct": 0, "short": "the volume displaced by all the pistons during one revolution of the crankshaft.", "expl": "Total piston displacement is the volume ALL the pistons sweep in one full revolution of the crankshaft — bore area × stroke × number of cylinders. It is 'all pistons, one revolution,' not one piston and not two revolutions.", "cite": "FAA-H-8083-30B, p. 3-21", "topicName": "Applied Aircraft Math (Displacement, Ratios, Force)", "fig": null}, {"id": "8398", "q": "What force is exerted on the piston in a hydraulic cylinder if the area of the piston is 1.2 square inches and the fluid pressure is 850 PSI?", "options": ["960 pounds.", "1,020 pounds.", "850 pounds."], "correct": 1, "short": "1,020 pounds.", "expl": "Force = pressure × area (Applied Mathematics Formula Sheet, Fig. 3-23). Here 850 psi acts on 1.2 sq in: 850 × 1.2 = 1,020 pounds of force on the piston.", "cite": "FAA-H-8083-30B, p. 3-23", "topicName": "Applied Aircraft Math (Displacement, Ratios, Force)", "fig": null}, {"id": "8403", "q": "What is the piston displacement of a master cylinder with a 1.5-inch diameter bore and a piston stroke of 4 inches?", "options": ["9.4247 cubic inches.", "6.1541 cubic inches.", "7.0686 cubic inches."], "correct": 2, "short": "7.0686 cubic inches.", "expl": "Piston displacement = bore area × stroke, and bore area = 0.7854 × D². 0.7854 × 1.5² = 1.767 sq in; × 4 in stroke = 7.0686 cubic inches.", "cite": "FAA-H-8083-30B, p. 3-21", "topicName": "Applied Aircraft Math (Displacement, Ratios, Force)", "fig": null}, {"id": "8406", "q": "A four-cylinder aircraft engine has a cylinder bore of 3.78 inches and is 8.5 inches deep. With the piston on bottom center, the top of the piston measures 4.0 inches from the bottom of the cylinder. What is the approximate piston displacement of this engine?", "options": ["200 cubic inches.", "360 cubic inches.", "235 cubic inches."], "correct": 0, "short": "200 cubic inches.", "expl": "One cylinder's displacement = 0.7854 × bore² × stroke. Stroke = 8.5 – 4.0 = 4.5 in swept. 0.7854 × 3.78² × 4.5 = 50.49 cu in; × 4 cylinders = 201.96 ≈ 200 cubic inches.", "cite": "FAA-H-8083-30B, p. 3-21", "topicName": "Applied Aircraft Math (Displacement, Ratios, Force)", "fig": null}, {"id": "8408", "q": "A six-cylinder engine with a bore of 3.5 inches, a cylinder height of 7 inches and a stroke of 4.5 inches will have a total piston displacement of", "options": ["256.88 cubic inches.", "259.77 cubic inches.", "43.3 cubic inches."], "correct": 1, "short": "259.77 cubic inches.", "expl": "Per cylinder = 0.7854 × bore² × stroke = 0.7854 × 3.5² × 4.5 = 43.3 cu in. Total for six cylinders: 43.3 × 6 = 259.77 cubic inches. (Cylinder height is a distractor — displacement uses the stroke.)", "cite": "FAA-H-8083-30B, p. 3-21", "topicName": "Applied Aircraft Math (Displacement, Ratios, Force)", "fig": null}, {"id": "8411", "q": "If the volume of a cylinder with the piston at bottom center is 84 cubic inches and the piston displacement is 70 cubic inches, then the compression ratio is", "options": ["7:1", "1.2:1", "6:1"], "correct": 2, "short": "6:1", "expl": "Compression ratio = volume with piston at bottom ÷ volume with piston at top. Top volume = 84 – 70 = 14 cu in. Ratio = 84 ÷ 14 = 6, i.e. 6:1.", "cite": "FAA-H-8083-30B, p. 3-7", "topicName": "Applied Aircraft Math (Displacement, Ratios, Force)", "fig": null}, {"id": "8415", "q": "A certain aircraft bolt has an overall length of 1-1/2 inches, with a shank length of 1-3/16 inches, and a threaded portion length of 5/8 inch. What is the grip length?", "options": [".5625 inch.", ".8750 inch.", ".3125 inch."], "correct": 0, "short": ".5625 inch.", "expl": "Grip length = shank length minus the threaded portion that is not in the grip: 1-3/16 in – 5/8 in = 1.1875 – 0.625 = 0.5625 inch. Line up the fractions (a subtraction of mixed numbers) before subtracting.", "cite": "FAA-H-8083-30B, p. 3-4", "topicName": "Applied Aircraft Math (Displacement, Ratios, Force)", "fig": null}, {"id": "8431", "q": "How much current does a 30-volt, 1/2 horsepower motor that is 85 percent efficient draw from the bus? (Note: 1 horsepower = 746 watts)", "options": ["12.4 amperes.", "14.6 amperes.", "14.3 amperes."], "correct": 1, "short": "14.6 amperes.", "expl": "Watts out = ½ hp × 746 = 373 W; watts in = 373 ÷ 0.85 efficiency = 438.8 W. Current = watts ÷ volts = 438.8 ÷ 30 = 14.6 amperes drawn from the bus.", "cite": "FAA-H-8083-30B, p. 3-23", "topicName": "Applied Aircraft Math (Displacement, Ratios, Force)", "fig": null}]}, {"code": "MACHINES", "title": "Work, Power, Force & Simple Machines", "ref": "FAA-H-8083-30B Ch.3 & Ch.5", "qs": [{"id": "8468", "q": "An engine that weighs 350 pounds is removed from an aircraft by means of a mobile hoist. The engine is raised 3 feet above its attachment mount, and the entire assembly is then moved forward 12 feet. A constant force of 70 pounds is required to move the loaded hoist. What is the total work input required to move the hoist?", "options": ["840 foot-pounds.", "1,890 foot-pounds.", "1,050 foot-pounds."], "correct": 0, "short": "840 foot-pounds.", "expl": "Work = force × distance, and only the work to MOVE the hoist is asked. The hoist is pushed 12 ft with a constant 70-lb force: 12 × 70 = 840 foot-pounds. The engine weight and lift height are extra information.", "cite": "FAA-H-8083-30B, p. 5-4", "topicName": "Work, Power, Force & Simple Machines", "fig": null}, {"id": "8471", "q": "(Refer to Figure 61.) The amount of force applied to rope A to lift the weight is", "options": ["12 pounds.", "15 pounds.", "20 pounds."], "correct": 1, "short": "15 pounds.", "expl": "A block and tackle's mechanical advantage equals the number of rope strands supporting the load. Four supporting ropes means the pull is the weight ÷ 4 = 60 ÷ 4 = 15 pounds (pulled four times as far).", "cite": "FAA-H-8083-30B, p. 5-10", "topicName": "Work, Power, Force & Simple Machines", "fig": "61"}, {"id": "8477", "q": "How much work input is required to lower (not drop) a 120-pound weight from the top of a 3-foot table to the floor?", "options": ["120 pounds of force.", "40 foot-pounds.", "360 foot-pounds."], "correct": 2, "short": "360 foot-pounds.", "expl": "It takes as much force to hold a weight back going down as to lift it, so work is still force × distance = 120 lb × 3 ft = 360 foot-pounds. Note the unit — work is in foot-pounds, not pounds.", "cite": "FAA-H-8083-30B, p. 5-4", "topicName": "Work, Power, Force & Simple Machines", "fig": null}, {"id": "8480", "q": "In physics, which of the following factors are necessary to determine power?", "options": ["Force exerted, distance moved, and time required.", "Force exerted, distance moved, and work.", "Distance moved and time required."], "correct": 0, "short": "Force exerted, distance moved, and time required.", "expl": "Power is the rate of doing work, so you need the force, the distance it moves, AND the time taken. Work alone (force × distance) has no time in it, so 'force, distance, and time' is the complete set.", "cite": "FAA-H-8083-30B, p. 5-6", "topicName": "Work, Power, Force & Simple Machines", "fig": null}, {"id": "8481", "q": "What force must be applied to roll a 120-pound barrel up an inclined plane 9 feet long to a height of 3 feet (disregard friction)? L÷I=R÷E L = Length of ramp, measured along the slope. I = Height of ramp. R = Weight of object to be raised or lowered. E = Force required to raise or lower object.", "options": ["120 pounds.", "40 pounds.", "360 pounds."], "correct": 1, "short": "40 pounds.", "expl": "An inclined plane trades distance for force: effort = weight × (height ÷ ramp length) = 120 × (3 ÷ 9) = 40 pounds. You roll it three times as far as you lift it, so the force is one-third the weight.", "cite": "FAA-H-8083-30B, p. 5-11", "topicName": "Work, Power, Force & Simple Machines", "fig": null}, {"id": "8487-1", "q": "Which of the following is Newton’s first law of motion, generally termed the law of inertia?", "options": ["To every action there is an equal and opposite reaction. If a force is applied to an object, the object will supply a resistive force exactly equal to and in the opposite direction of the force applied.", "Force is proportional to the product of mass and acceleration. When a force acts upon a body, the momentum of that body is changed.", "Objects at rest tend to remain at rest and objects in motion tend to remain in motion at the same speed and in the same direction, unless acted on by an external force."], "correct": 2, "short": "Objects at rest tend to remain at rest and objects in motion tend to remain in motion at the same speed and in the same direction, unless acted on by an external force.", "expl": "Newton's first law (the law of inertia) says an object at rest stays at rest and an object in motion keeps moving in a straight line at constant speed unless an outside force acts on it. That is the 'objects at rest / objects in motion' statement — the action-reaction one is the third law.", "cite": "FAA-H-8083-30B, p. 5-16", "topicName": "Work, Power, Force & Simple Machines", "fig": null}]}, {"code": "FLUIDS", "title": "Fluids, Pressure, Pascal & Bernoulli", "ref": "FAA-H-8083-30B Ch.3 & Ch.5", "qs": [{"id": "8216", "q": "Which statement concerning Bernoulli’s principle is true?", "options": ["The pressure of a fluid decreases at points where the velocity of the fluid increases.", "The pressure of a fluid increases at points where the velocity of the fluid increases.", "It applies only to gases and vaporized liquids."], "correct": 0, "short": "The pressure of a fluid decreases at points where the velocity of the fluid increases.", "expl": "Bernoulli's principle: in a moving fluid, where velocity is high the pressure is low, and where velocity is low the pressure is high (energy is traded between the two). So the true statement is that a fluid's pressure DECREASES where its velocity increases.", "cite": "FAA-H-8083-30B, p. 5-29", "topicName": "Fluids, Pressure, Pascal & Bernoulli", "fig": null}, {"id": "8465", "q": "If a double-acting actuating cylinder in a 3,000 psi system has a piston with a surface area of three square inches on the extension side, and a rod with a cross-section area of one square inch attached to the piston on the other side, approximately how much force will the actuator be able to produce when retracting?", "options": ["9,000 pounds.", "6,000 pounds.", "3,000 pounds."], "correct": 1, "short": "6,000 pounds.", "expl": "By Pascal's law, force = pressure × effective area. On the retract stroke the rod blocks part of the piston, so the effective area is 3 – 1 = 2 sq in: 2 × 3,000 = 6,000 pounds of force.", "cite": "FAA-H-8083-30B, p. 5-27", "topicName": "Fluids, Pressure, Pascal & Bernoulli", "fig": null}, {"id": "8470", "q": "Under which conditions will the rate of flow of a liquid through a metering orifice (or jet) be the greatest (all other factors being equal)?", "options": ["Unmetered pressure, 18 psi; metered pressure, 17.5 psi; atmospheric pressure, 14.5 psi.", "Unmetered pressure, 23 psi; metered pressure, 12 psi; atmospheric pressure, 14.3 psi.", "Unmetered pressure, 17 PSI; metered pressure, 5 psi; atmospheric pressure, 14.7 psi."], "correct": 2, "short": "Unmetered pressure, 17 PSI; metered pressure, 5 psi; atmospheric pressure, 14.7 psi.", "expl": "Flow through a metering jet depends on the pressure DIFFERENCE across it — atmospheric pressure pushes equally on both sides and cancels out. The 17-psi/5-psi pair has the largest differential (12 psi), so it gives the greatest flow.", "cite": "FAA-H-8083-30B, p. 5-27", "topicName": "Fluids, Pressure, Pascal & Bernoulli", "fig": null}, {"id": "8479", "q": "If the fluid pressure is 800 PSI in a 1/2-inch line supplying an actuating cylinder with a piston area of 10 square inches, the force exerted on the piston will be", "options": ["8,000 pounds.", "4,000 pounds.", "800 pounds."], "correct": 0, "short": "8,000 pounds.", "expl": "Force = pressure × piston area (Pascal's law); the supply-line size does not affect the force produced. 800 psi × 10 sq in = 8,000 pounds on the piston.", "cite": "FAA-H-8083-30B, p. 5-27", "topicName": "Fluids, Pressure, Pascal & Bernoulli", "fig": null}]}, {"code": "HEATGAS", "title": "Heat, Temperature & Gas Laws", "ref": "FAA-H-8083-30B Ch.3 & Ch.5", "qs": [{"id": "8466", "q": "The boiling point of a given liquid varies", "options": ["directly with pressure.", "inversely with pressure.", "directly with density."], "correct": 0, "short": "directly with pressure.", "expl": "Boiling point rises and falls with the pressure above the liquid: more pressure holds the vapor down and raises the boiling point, less pressure lowers it. So the boiling point varies DIRECTLY with pressure.", "cite": "FAA-H-8083-30B, p. 5-22", "topicName": "Heat, Temperature & Gas Laws", "fig": null}, {"id": "8467", "q": "Which of the following is NOT considered a method of heat transfer?", "options": ["Convection.", "Diffusion.", "Conduction."], "correct": 1, "short": "Diffusion.", "expl": "Heat moves three ways: conduction (through direct contact), convection (through moving fluid/air currents), and radiation (through electromagnetic waves). 'Diffusion' is not one of the three methods of heat transfer.", "cite": "FAA-H-8083-30B, p. 5-19", "topicName": "Heat, Temperature & Gas Laws", "fig": null}, {"id": "8475", "q": "If the volume of a confined gas is doubled (without the addition of more gas), the pressure will (assume the temperature remains constant)", "options": ["increase in direct proportion to the volume increase.", "remain the same.", "be reduced to one-half its original value."], "correct": 2, "short": "be reduced to one-half its original value.", "expl": "Boyle's law: at constant temperature, pressure and volume are inversely related. Double the volume and the pressure drops to one-half its original value. Sanity check: bigger space for the same gas means less pressure.", "cite": "FAA-H-8083-30B, p. 5-24", "topicName": "Heat, Temperature & Gas Laws", "fig": null}, {"id": "8476", "q": "If the temperature of a confined liquid is held constant and its pressure is tripled, the volume will", "options": ["remain the same.", "triple.", "be reduced to one-third its original volume."], "correct": 0, "short": "remain the same.", "expl": "Liquids are essentially incompressible — squeezing them harder does not shrink them. So tripling the pressure on a confined liquid at constant temperature leaves the volume essentially unchanged.", "cite": "FAA-H-8083-30B, p. 5-26", "topicName": "Heat, Temperature & Gas Laws", "fig": null}, {"id": "8482", "q": "Which statement concerning heat and/or temperature is true?", "options": ["There is an inverse relationship between temperature and heat.", "Temperature is a measure of the kinetic energy of the molecules of any substance.", "Temperature is a measure of the potential energy of the molecules of any substance."], "correct": 1, "short": "Temperature is a measure of the kinetic energy of the molecules of any substance.", "expl": "Temperature is a measure of the average KINETIC energy (the motion) of a substance's molecules — the faster they move, the higher the temperature. Heat is energy in transit; temperature measures molecular motion, not potential energy.", "cite": "FAA-H-8083-30B, p. 5-21", "topicName": "Heat, Temperature & Gas Laws", "fig": null}, {"id": "8485", "q": "If both the volume and the absolute temperature of a confined gas are doubled, the pressure will", "options": ["be halved.", "become four times as great.", "not change."], "correct": 2, "short": "not change.", "expl": "By the general gas law, pressure is directly proportional to absolute temperature and inversely proportional to volume. Doubling both at once: the temperature effect (×2) and the volume effect (÷2) cancel, so the pressure does not change.", "cite": "FAA-H-8083-30B, p. 5-25", "topicName": "Heat, Temperature & Gas Laws", "fig": null}]}, {"code": "ATMO", "title": "Atmosphere, Humidity & Sound", "ref": "FAA-H-8083-30B Ch.3 & Ch.5", "qs": [{"id": "8469", "q": "Which condition is the actual amount of water vapor in a mixture of air and water?", "options": ["Absolute humidity.", "Relative humidity.", "Dewpoint."], "correct": 0, "short": "Absolute humidity.", "expl": "Absolute humidity is the ACTUAL amount of water vapor present in a given volume of air (e.g. grams per cubic meter). Relative humidity is a ratio and dew point is a temperature, so the 'actual amount' is absolute humidity.", "cite": "FAA-H-8083-30B, p. 5-35", "topicName": "Atmosphere, Humidity & Sound", "fig": null}, {"id": "8472", "q": "Which will weigh the least?", "options": ["98 parts of dry air and 2 parts of water vapor.", "35 parts of dry air and 65 parts of water vapor.", "50 parts of dry air and 50 parts of water vapor."], "correct": 1, "short": "35 parts of dry air and 65 parts of water vapor.", "expl": "Water vapor is lighter than dry air, so the more water vapor a sample holds, the less it weighs. The 35-parts-dry-air / 65-parts-water-vapor mix has the most water vapor, so it weighs the least.", "cite": "FAA-H-8083-30B, p. 5-34", "topicName": "Atmosphere, Humidity & Sound", "fig": null}, {"id": "8473", "q": "Which is the ratio of the water vapor actually present in the atmosphere to the amount that would be present if the air were saturated at the prevailing temperature and pressure?", "options": ["Absolute humidity.", "Dewpoint.", "Relative humidity."], "correct": 2, "short": "Relative humidity.", "expl": "Relative humidity is the RATIO of the water vapor actually present to the amount the air could hold if saturated at that temperature and pressure. Absolute humidity is an amount and dew point is a temperature, so the ratio is relative humidity.", "cite": "FAA-H-8083-30B, p. 5-35", "topicName": "Atmosphere, Humidity & Sound", "fig": null}, {"id": "8474", "q": "The speed of sound in the atmosphere", "options": ["changes with a change in temperature.", "varies according to the frequency of the sound.", "changes with a change in pressure."], "correct": 0, "short": "changes with a change in temperature.", "expl": "The speed of sound in air depends on the air's temperature — warmer air carries sound faster. It is not set by the sound's frequency or by pressure, so it changes with a change in temperature.", "cite": "FAA-H-8083-30B, p. 5-31", "topicName": "Atmosphere, Humidity & Sound", "fig": null}, {"id": "8474-1", "q": "The speed of sound in the atmosphere is most affected by variations in which of the following?", "options": ["Sound frequency.", "Ambient temperature.", "Barometric pressure."], "correct": 1, "short": "Ambient temperature.", "expl": "Of the choices, ambient (air) temperature is what most affects the speed of sound; frequency and barometric pressure do not control it. Warm air = faster sound.", "cite": "FAA-H-8083-30B, p. 5-31", "topicName": "Atmosphere, Humidity & Sound", "fig": null}, {"id": "8478", "q": "Which atmospheric conditions will cause the true landing speed of an aircraft to be the greatest?", "options": ["Low temperature with low humidity.", "High temperature with low humidity.", "High temperature with high humidity."], "correct": 2, "short": "High temperature with high humidity.", "expl": "True landing speed is highest when the air is least dense (thin air = more ground speed for the same lift). High temperature and high humidity both lower air density, so that combination gives the greatest true landing speed.", "cite": "FAA-H-8083-30B, p. 5-34", "topicName": "Atmosphere, Humidity & Sound", "fig": null}, {"id": "8483", "q": "What is absolute humidity?", "options": ["The actual amount of the water vapor in a mixture of air and water.", "The temperature to which humid air must be cooled at constant pressure to become saturated.", "The ratio of the water vapor actually present in the atmosphere to the amount that would be present if the air were saturated at the prevailing temperature and pressure."], "correct": 0, "short": "The actual amount of the water vapor in a mixture of air and water.", "expl": "Absolute humidity is the actual amount of water vapor in a mixture of air and water (measured as mass per unit volume). The 'temperature to which air must be cooled' is dew point, and the 'ratio' answer is relative humidity.", "cite": "FAA-H-8083-30B, p. 5-35", "topicName": "Atmosphere, Humidity & Sound", "fig": null}, {"id": "8484", "q": "The temperature to which humid air must be cooled at constant pressure to become saturated is called", "options": ["absolute humidity.", "dewpoint.", "relative humidity."], "correct": 1, "short": "dewpoint.", "expl": "Dew point is the temperature to which humid air must be cooled, at constant pressure, for it to become saturated (water starts to condense). Absolute and relative humidity describe amounts/ratios, not that temperature.", "cite": "FAA-H-8083-30B, p. 5-36", "topicName": "Atmosphere, Humidity & Sound", "fig": null}]}, {"code": "AERO", "title": "Aerodynamics & Theory of Flight", "ref": "FAA-H-8083-30B Ch.3 & Ch.5", "qs": [{"id": "8486", "q": "If all, or a significant part of a stall strip is missing on an airplane wing, a likely result will be", "options": ["asymmetrical lateral control at or near stall angles of attack.", "decreased lift in the area of installation at high angles of attack.", "asymmetrical lateral control at low angles of attack."], "correct": 0, "short": "asymmetrical lateral control at or near stall angles of attack.", "expl": "A stall strip forces the wing root to stall before the tip, keeping the ailerons (out near the tips) effective. If part of one strip is missing, that wing behaves differently from the other at high angle of attack — giving asymmetrical lateral control at or near stall angles of attack.", "cite": "FAA-H-8083-30B, p. 5-39", "topicName": "Aerodynamics & Theory of Flight", "fig": null}, {"id": "8486-1", "q": "The purpose of stall strips on airplane wings is to", "options": ["increase lift in the areas of installation.", "ensure that the wing root areas stall first.", "prevent stall in the areas of installation."], "correct": 1, "short": "ensure that the wing root areas stall first.", "expl": "Stall strips are placed on the inboard leading edge so the wing ROOT stalls first. That keeps airflow over the outboard ailerons longer, preserving roll control as the stall develops. Their purpose is to ensure the wing root areas stall first.", "cite": "FAA-H-8083-30B, p. 5-39", "topicName": "Aerodynamics & Theory of Flight", "fig": null}, {"id": "8487", "q": "An airplane wing is designed to produce lift resulting from", "options": ["positive air pressure below and above the wing’s surface along with the downward deflection of air.", "negative air pressure below the wing’s surface and positive air pressure above the wing’s surface along with the downward deflection of air.", "positive air pressure below the wing’s surface and negative air pressure above the wing’s surface along with the downward deflection of air."], "correct": 2, "short": "positive air pressure below the wing’s surface and negative air pressure above the wing’s surface along with the downward deflection of air.", "expl": "A wing makes lift from a pressure difference plus the downward deflection of air: higher (positive) pressure below the wing and lower (negative) pressure above it, together with air being pushed down. That 'positive below, negative above, air deflected down' description is the correct one.", "cite": "FAA-H-8083-30B, p. 5-37", "topicName": "Aerodynamics & Theory of Flight", "fig": null}, {"id": "8488", "q": "The purpose of aircraft wing dihedral is to", "options": ["increase lateral stability.", "increase longitudinal stability.", "increase lift coefficient of the wing."], "correct": 0, "short": "increase lateral stability.", "expl": "Dihedral — the upward slant of the wings from the fuselage — increases LATERAL (roll) stability by making a slipping airplane tend to roll back level. It works on the longitudinal axis, so its purpose is to increase lateral stability.", "cite": "FAA-H-8083-30B, p. 5-42", "topicName": "Aerodynamics & Theory of Flight", "fig": null}, {"id": "8489", "q": "Aspect ratio of a wing is defined as the ratio of the", "options": ["wingspan to the wing root.", "wingspan to the mean chord.", "square of the chord to the wingspan."], "correct": 1, "short": "wingspan to the mean chord.", "expl": "Aspect ratio is the ratio of a wing's span to its mean (average) chord — a long, slender wing has a high aspect ratio. So it is wingspan to mean chord.", "cite": "FAA-H-8083-30B, p. 5-40", "topicName": "Aerodynamics & Theory of Flight", "fig": null}, {"id": "8490", "q": "A wing with a very high aspect ratio (in comparison with a low aspect ratio wing) will have", "options": ["increased drag at high angles of attack.", "poor control qualities at low airspeeds.", "a low stall speed."], "correct": 2, "short": "a low stall speed.", "expl": "A high-aspect-ratio (long, slender) wing is efficient and produces less induced drag, which gives it a LOW stall speed compared with a short, low-aspect-ratio wing. So the high-aspect-ratio wing has a low stall speed.", "cite": "FAA-H-8083-30B, p. 5-40", "topicName": "Aerodynamics & Theory of Flight", "fig": null}, {"id": "8491", "q": "The desired effect of using winglets on an aircraft’s wingtips is to", "options": ["increase the lift to drag ratio.", "reduce the aspect ratio.", "optimize wing dihedral and improve lateral stability."], "correct": 0, "short": "increase the lift to drag ratio.", "expl": "Winglets are small upturned tips that cut down the spanwise flow and the wingtip vortices that cause induced drag. Less drag for the same lift means the desired effect is to increase the lift-to-drag (L/D) ratio.", "cite": "FAA-H-8083-30B, p. 5-40", "topicName": "Aerodynamics & Theory of Flight", "fig": null}, {"id": "8491-1", "q": "The main rotor system on a helicopter is classified in three groups. Which of those listed is NOT one of these groups?", "options": ["The fully articulated rotor system.", "The flexible-beam rotor system.", "The semi-rigid rotor system."], "correct": 1, "short": "The flexible-beam rotor system.", "expl": "Main rotor systems are grouped as fully articulated, semi-rigid, and rigid. 'Flexible-beam' is not one of those three classifications, so it is the one that is NOT a main-rotor-system group.", "cite": "FAA-H-8083-30B, p. 5-50", "topicName": "Aerodynamics & Theory of Flight", "fig": null}, {"id": "8491-2", "q": "Which of the following statements is correct?", "options": ["When the cyclic pitch control lever is raised, the blade angle of all the rotor blades increases uniformly and they create the lift that allows the helicopter to take off vertically.", "When the collective pitch control lever is raised, the blade angle of the aft rotor blades decreases uniformly and they create the lift that allows the helicopter to take off vertically.", "When the collective pitch control lever is raised, the blade angle of all the rotor blades increases uniformly and they create the lift that allows the helicopter to take off vertically."], "correct": 2, "short": "When the collective pitch control lever is raised, the blade angle of all the rotor blades increases uniformly and they create the lift that allows the helicopter to take off vertically.", "expl": "Raising the COLLECTIVE pitch lever increases the blade angle of all the rotor blades uniformly, creating the lift that lets the helicopter climb straight up. The cyclic lever tilts the rotor for direction; the collective changes all blades together, so that is the correct statement.", "cite": "FAA-H-8083-30B, p. 5-54", "topicName": "Aerodynamics & Theory of Flight", "fig": null}]}]};
